      {overview.trends.length<3?<div className="trend-empty"><Activity size={20}/><p>Trends will appear after a few weeks of activity.</p></div>:tableView?<div className="table-wrap"><table className="data-table"><caption className="sr-only">University trends over time</caption><thead><tr><th scope="col">Week</th><th scope="col">Verified students</th><th scope="col">Reviews</th></tr></thead><tbody>{trendRows.map((row)=><tr key={row.week_start}><td>{new Date(row.week_start).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</td><td>{row.verified_total}</td><td>{row.reviews}</td></tr>)}</tbody></table></div>:chartVisible?<Suspense fallback={<div className="skeleton" style={{height:240}}/>}><TrendChart data={trendRows}/></Suspense>:<div className="skeleton trend-skeleton" aria-label="Trend chart loads when visible"/>}
